const BUNDLED_FILES=['data/pyq/2021_2026/2021.json','data/pyq/2021_2026/2022.json','data/pyq/2021_2026/2023.json','data/pyq/2021_2026/2024.json','data/pyq/2021_2026/2024-expansion-a.json','data/pyq/2021_2026/2024-expansion-b.json','data/pyq/2021_2026/2024-expansion-c.json','data/pyq/2021_2026/2024-expansion-d.json','data/pyq/2021_2026/2025.json','data/pyq/2021_2026/2025-expansion-a.json','data/pyq/2021_2026/2025-expansion-b.json','data/pyq/2021_2026/2025-expansion-c.json','data/pyq/2021_2026/2026.json'];
const QUESTION_MANIFEST='data/pyq/manifest.json';
const DB_NAME='neetpg2027-static-v2';
const DB_VERSION=2;
const SETTINGS_KEY='neetpg2027-v2-settings';
const OLD_KEY='neetpg2027-static-progress-v1';
const QSTATE_MIRROR='neetpg2027:qstate-mirror';
const DEFAULTS={theme:'system',accent:'green',density:'comfortable',font:'16',defaultMode:'smart',defaultCount:'15',shuffle:true,labels:true,autoExplain:true,presets:[]};
const app={db:null,questions:[],qMap:new Map(),states:new Map(),attempts:[],sessions:[],custom:[],prefs:{...DEFAULTS},session:null,lastSession:null,filteredBank:[],installPrompt:null,toastTimer:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const now=()=>Date.now();
const iso=t=>new Date(t).toISOString();
const dayKey=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const emitUi=(name,detail={})=>window.dispatchEvent(new CustomEvent(`neetpg:${name}`,{detail}));
const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x};
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(app.toastTimer);app.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function difficultyName(n){return n<=1?'Easy':n===2?'Medium':'Hard'}
function parseMeta(q){const ref=q.reference_text||'';const sm=ref.match(/Subject:\s*([^;]+)/i),tm=ref.match(/Topic:\s*([^.;]+)/i);return {...q,subject:(q.subject||sm?.[1]||'Uncategorized').trim(),topic:(q.topic||tm?.[1]||'General').trim(),difficulty:Number(q.difficulty||2),is_clinical:!!q.is_clinical,is_integrated:!!q.is_integrated}}
function stateFor(qid){return app.states.get(qid)||{qid,attempts:0,correct:0,incorrect:0,lastCorrect:null,bookmarked:false,flagged:false,note:'',dueAt:null,intervalDays:0,ease:2.5,streak:0,updatedAt:null}}

function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('runtime'))db.createObjectStore('runtime',{keyPath:'id'});if(!db.objectStoreNames.contains('qstate'))db.createObjectStore('qstate',{keyPath:'qid'});if(!db.objectStoreNames.contains('attempts'))db.createObjectStore('attempts',{keyPath:'id',autoIncrement:true});if(!db.objectStoreNames.contains('sessions'))db.createObjectStore('sessions',{keyPath:'id'});if(!db.objectStoreNames.contains('custom'))db.createObjectStore('custom',{keyPath:'external_id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function store(mode,name){return app.db.transaction(name,mode).objectStore(name)}
function dbAll(name){return new Promise((res,rej)=>{const r=store('readonly',name).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function dbPut(name,val){return new Promise((res,rej)=>{const tx=app.db.transaction(name,'readwrite'),r=tx.objectStore(name).put(val);tx.oncomplete=()=>res(r.result);tx.onerror=tx.onabort=()=>rej(tx.error||new Error('Save failed'))})}
async function dbAdd(name,val){return new Promise((res,rej)=>{const tx=app.db.transaction(name,'readwrite'),r=tx.objectStore(name).add(val);tx.oncomplete=()=>res(r.result);tx.onerror=tx.onabort=()=>rej(tx.error||new Error('Save failed'))})}
function dbClear(name){return new Promise((res,rej)=>{const r=store('readwrite',name).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function dbDeleteWhere(name,predicate){return new Promise((res,rej)=>{const tx=app.db.transaction(name,'readwrite'),os=tx.objectStore(name),r=os.openCursor();r.onerror=()=>rej(r.error);r.onsuccess=()=>{const cur=r.result;if(!cur)return;if(predicate(cur.value))cur.delete();cur.continue()};tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
const isLegacyHighYield100Id=qid=>/^hy100-\d+$/i.test(String(qid||''));
async function purgeLegacyHighYield100(){await dbDeleteWhere('qstate',x=>isLegacyHighYield100Id(x?.qid));await dbDeleteWhere('attempts',x=>isLegacyHighYield100Id(x?.qid))}
function mirrorQState(){try{localStorage.setItem(QSTATE_MIRROR,JSON.stringify([...app.states.values()].map(x=>({qid:x.qid,attempts:Number(x.attempts||0),correct:Number(x.correct||0),incorrect:Number(x.incorrect||0),lastCorrect:x.lastCorrect,updatedAt:x.updatedAt||null}))))}catch(_){}}
async function loadState(){await purgeLegacyHighYield100();app.custom=await dbAll('custom');const st=await dbAll('qstate');app.states=new Map(st.map(x=>[x.qid,x]));app.attempts=(await dbAll('attempts')).sort((a,b)=>a.ts-b.ts);app.sessions=(await dbAll('sessions')).sort((a,b)=>b.startedAt-a.startedAt);mirrorQState()}
async function questionBundleFiles(){try{const r=await fetch(QUESTION_MANIFEST,{cache:'no-store'});if(r.ok){const data=await r.json(),files=Array.isArray(data)?data:data.files;if(Array.isArray(files)&&files.length)return files.filter(f=>typeof f==='string'&&f.endsWith('.json'))}}catch(e){console.warn('Question manifest unavailable; using fallback bundle list',e)}return BUNDLED_FILES}
async function loadQuestions(){
 const files=await questionBundleFiles(),parts=await Promise.allSettled(files.map(async f=>{const r=await fetch(f);if(!r.ok)throw new Error(f);return r.json()}));
 app.failedBundles=files.filter((_,i)=>parts[i].status==='rejected');
 const bundled=parts.filter(x=>x.status==='fulfilled').flatMap(x=>x.value).map(parseMeta),custom=app.custom.map(q=>parseMeta({...q,source:'custom'})),seen=new Set();
 app.questions=[...bundled,...custom].filter(q=>q.external_id&&!seen.has(q.external_id)&&seen.add(q.external_id));app.qMap=new Map(app.questions.map(q=>[q.external_id,q]));
 let banner=$('#bundleStatus');if(!banner){banner=document.createElement('div');banner.id='bundleStatus';banner.className='callout';$('.content').prepend(banner)}banner.hidden=!app.failedBundles.length;
 if(app.failedBundles.length){banner.replaceChildren(document.createTextNode(`${app.failedBundles.length} question bundles unavailable. Available questions remain usable. `));const b=document.createElement('button');b.className='btn small';b.textContent='Retry downloads';b.onclick=async()=>{b.disabled=true;await loadQuestions();populateFilters();renderAll()};banner.append(b)}
 emitUi('questions-loaded');
}
function loadPrefs(){try{app.prefs={...DEFAULTS,...JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')}}catch{app.prefs={...DEFAULTS}}applyPrefs()}
function savePrefs(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(app.prefs));localStorage.setItem('neetpg2027-v2-settings-updated',String(Date.now()))}catch{toast('Settings applied for this visit; device storage is unavailable.')}applyPrefs();emitUi('prefs-change')}
function applyPrefs(){let theme=app.prefs.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.body.dataset.theme=theme;document.documentElement.style.colorScheme=theme;const toggle=$('#themeToggle');if(toggle){toggle.textContent=theme==='dark'?'☀ Light':'☾ Dark';toggle.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');toggle.setAttribute('aria-pressed',String(theme==='dark'))}document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#141418':'#f7f8f7');document.body.dataset.accent=app.prefs.accent;document.body.dataset.density=app.prefs.density;document.documentElement.style.setProperty('--font',`${app.prefs.font}px`);emitUi('theme-change',{theme})}
async function migrateV1(){if(localStorage.getItem('neetpg2027-v2-migrated'))return;let old;try{old=JSON.parse(localStorage.getItem(OLD_KEY)||'null')}catch{}if(old?.attempts){for(const [qid,a] of Object.entries(old.attempts)){let s=stateFor(qid);s={...s,attempts:1,correct:a.correct?1:0,incorrect:a.correct?0:1,lastCorrect:!!a.correct,bookmarked:(old.bookmarks||[]).includes(qid),updatedAt:a.at||iso(now())};app.states.set(qid,s);await dbPut('qstate',s);await dbAdd('attempts',{qid,correct:!!a.correct,selected:a.selected||null,confidence:null,mistake:'',note:'',ts:new Date(a.at||Date.now()).getTime(),elapsed:0,sessionId:'migration'})}}localStorage.setItem('neetpg2027-v2-migrated','1');await loadState()}

function subjectStats(){const out={};for(const a of app.attempts){const q=app.qMap.get(a.qid);if(!q)continue;const k=q.subject;out[k]??={attempts:0,correct:0};out[k].attempts++;if(a.correct)out[k].correct++}return out}
function topicStats(){const out={};for(const a of app.attempts){const q=app.qMap.get(a.qid);if(!q)continue;const k=`${q.subject} · ${q.topic}`;out[k]??={attempts:0,correct:0};out[k].attempts++;if(a.correct)out[k].correct++}return out}
function dueQuestions(){const t=now();return app.questions.filter(q=>{const s=stateFor(q.external_id);return s.dueAt&&s.dueAt<=t})}
function incorrectQuestions(){return app.questions.filter(q=>stateFor(q.external_id).lastCorrect===false)}
function unseenQuestions(){return app.questions.filter(q=>!stateFor(q.external_id).attempts)}
function bookmarkedQuestions(){return app.questions.filter(q=>stateFor(q.external_id).bookmarked)}
function calcStreak(){if(!app.attempts.length)return 0;const days=new Set(app.attempts.map(a=>dayKey(a.ts)));let d=new Date();let count=0;const today=dayKey(d);if(!days.has(today)){d.setDate(d.getDate()-1);if(!days.has(dayKey(d)))return 0}while(days.has(dayKey(d))){count++;d.setDate(d.getDate()-1)}return count}
function smartScore(q,subStats=subjectStats()){const s=stateFor(q.external_id);let score=Math.random()*6;if(s.dueAt&&s.dueAt<=now())score+=100;if(s.lastCorrect===false)score+=78;if(!s.attempts)score+=38;if(s.bookmarked)score+=14;if(s.flagged)score+=8;const ss=subStats[q.subject];if(ss&&ss.attempts>=3&&ss.correct/ss.attempts<.65)score+=42;if(q.is_integrated)score+=6;if(q.difficulty>=2)score+=4;return score}
function getFilteredQuestions(cfg={}){let qs=[...app.questions];const mode=cfg.mode||'all';if(mode==='unseen')qs=unseenQuestions();else if(mode==='due')qs=dueQuestions();else if(mode==='incorrect')qs=incorrectQuestions();else if(mode==='bookmarked')qs=bookmarkedQuestions();if(cfg.subject&&cfg.subject!=='all')qs=qs.filter(q=>q.subject===cfg.subject);if(cfg.topic&&cfg.topic!=='all')qs=qs.filter(q=>q.topic===cfg.topic);if(cfg.difficulty&&cfg.difficulty!=='all')qs=qs.filter(q=>q.difficulty===Number(cfg.difficulty));if(cfg.clinical==='yes')qs=qs.filter(q=>q.is_clinical);if(cfg.clinical==='no')qs=qs.filter(q=>!q.is_clinical);if(cfg.integrated==='yes')qs=qs.filter(q=>q.is_integrated);if(cfg.integrated==='no')qs=qs.filter(q=>!q.is_integrated);const ss=subjectStats();if(mode==='smart'||cfg.order==='adaptive')qs.sort((a,b)=>smartScore(b,ss)-smartScore(a,ss));else if(cfg.order==='weakest')qs.sort((a,b)=>{const aa=ss[a.subject],bb=ss[b.subject],ar=aa?aa.correct/aa.attempts:1,br=bb?bb.correct/bb.attempts:1;return ar-br});else if(cfg.order==='random')qs=shuffle(qs);return qs}
function sessionConfigFromForm(){return{mode:$('#pMode').value,subject:$('#pSubject').value,topic:$('#pTopic').value,difficulty:$('#pDifficulty').value,clinical:$('#pClinical').value,integrated:$('#pIntegrated').value,count:Number($('#pCount').value),feedback:$('#pFeedback').value,timer:$('#pTimer').value,seconds:clamp(Number($('#pSeconds').value)||60,10,600),order:$('#pOrder').value,shuffle:$('#pShuffle').value==='default'?app.prefs.shuffle:$('#pShuffle').value==='yes'}}

async function persistQState(s){s.updatedAt=now();app.states.set(s.qid,s);await dbPut('qstate',s);mirrorQState();emitUi('progress-saved')}
async function toggleBookmark(qid){const s={...stateFor(qid),bookmarked:!stateFor(qid).bookmarked};await persistQState(s);renderAll();if(currentQ()?.external_id===qid)$('#qBookmark').textContent=`${s.bookmarked?'★':'☆'} Bookmark`;toast(s.bookmarked?'Bookmarked':'Bookmark removed')}
async function toggleFlag(qid){const s={...stateFor(qid),flagged:!stateFor(qid).flagged};await persistQState(s);renderAll();if(currentQ()?.external_id===qid)$('#qFlag').textContent=`${s.flagged?'⚑':'⚐'} Flag`;toast(s.flagged?'Flagged for review':'Flag removed')}
async function saveQuestionNote(qid,note){const s={...stateFor(qid),note:note.trim()};await persistQState(s);renderAll()}
async function recordAttempt(q,selected,extra={}){const correctOpt=q.options.find(o=>o.is_correct);const correct=selected!=null&&correctOpt&&selected===correctOpt.label;const s={...stateFor(q.external_id)};s.attempts=(s.attempts||0)+1;s.correct=(s.correct||0)+(correct?1:0);s.incorrect=(s.incorrect||0)+(correct?0:1);s.lastCorrect=correct;s.streak=correct?(s.streak||0)+1:0;s.updatedAt=now();const rec={qid:q.external_id,correct,selected:selected||null,confidence:extra.confidence||null,mistake:extra.mistake||'',note:extra.note||'',skipped:!selected,ts:now(),elapsed:extra.elapsed||0,sessionId:extra.sessionId||'',subject:q.subject,difficulty:q.difficulty};const id=await new Promise((resolve,reject)=>{const tx=app.db.transaction(['qstate','attempts'],'readwrite');tx.objectStore('qstate').put(s);const r=tx.objectStore('attempts').add(rec);tx.oncomplete=()=>resolve(r.result);tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Answer could not be saved'))});app.states.set(s.qid,s);mirrorQState();rec.id=id;app.attempts.push(rec);emitUi('progress-saved');return rec}
async function updateAttempt(rec){await dbPut('attempts',rec);const i=app.attempts.findIndex(x=>x.id===rec.id);if(i>=0)app.attempts[i]=rec;emitUi('progress-saved')}
async function applySrs(qid,rating){const s={...stateFor(qid)};let ease=s.ease||2.5,interval=s.intervalDays||0;if(rating==='again'){interval=10/(60*24);ease=Math.max(1.3,ease-.2)}else if(rating==='hard'){interval=interval<1?1:interval*1.2;ease=Math.max(1.3,ease-.15)}else if(rating==='good'){interval=interval<1?1:interval*ease}else if(rating==='easy'){interval=interval<1?3:interval*ease*1.3;ease=Math.min(3.2,ease+.15)}s.ease=ease;s.intervalDays=interval;s.dueAt=now()+interval*86400000;await persistQState(s);toast(`Next review ${interval<1?'in ~10 min':`in ${Math.max(1,Math.round(interval))} day${Math.round(interval)===1?'':'s'}`}`)}

function navigate(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('.nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const title=$('#topTitle');if(title)title.textContent=({dashboard:'Dashboard',practice:'Practice',review:'Review & SRS',bank:'Question Bank',analytics:'Analytics',settings:'Settings'})[view]||view;$('#sidebar')?.classList.remove('open');$('#mobileOverlay')?.classList.remove('show');if(view==='dashboard')renderDashboard();if(view==='review')renderReview();if(view==='bank')renderBank();if(view==='analytics')renderAnalytics();if(view==='settings')renderSettings();emitUi('route-change',{view})}
function populateFilters(){const subjects=[...new Set(app.questions.map(q=>q.subject))].sort();for(const id of ['pSubject','bankSubject']){const el=$(`#${id}`);const current=el.value;el.innerHTML='<option value="all">All subjects</option>'+subjects.map(s=>`<option>${escapeHtml(s)}</option>`).join('');if([...el.options].some(o=>o.value===current))el.value=current}updateTopics()}
function updateTopics(){const subject=$('#pSubject').value;const topics=[...new Set(app.questions.filter(q=>subject==='all'||q.subject===subject).map(q=>q.topic))].sort();const cur=$('#pTopic').value;$('#pTopic').innerHTML='<option value="all">All topics</option>'+topics.map(t=>`<option>${escapeHtml(t)}</option>`).join('');if([...$('#pTopic').options].some(o=>o.value===cur))$('#pTopic').value=cur}

function renderDashboard(){if(!$('#statTotal'))return;const attempted=app.questions.filter(q=>stateFor(q.external_id).attempts).length,total=app.questions.length,acc=app.attempts.length?Math.round(app.attempts.filter(a=>a.correct).length/app.attempts.length*100):null,due=dueQuestions().length,bms=bookmarkedQuestions().length;$('#statTotal').textContent=total;$('#statAttempted').textContent=attempted;$('#statCoverage').textContent=`${total?Math.round(attempted/total*100):0}% coverage`;$('#statAccuracy').textContent=acc==null?'—':`${acc}%`;$('#statDue').textContent=due;$('#navDue').textContent=due;$('#statStreak').textContent=calcStreak();$('#statBookmarks').textContent=bms;
 const smart=getFilteredQuestions({mode:'smart',order:'adaptive'}).slice(0,Number(app.prefs.defaultCount)||15);const mix={due:0,errors:0,unseen:0,weak:0};const ss=subjectStats();for(const q of smart){const s=stateFor(q.external_id);if(s.dueAt&&s.dueAt<=now())mix.due++;else if(s.lastCorrect===false)mix.errors++;else if(!s.attempts)mix.unseen++;else if(ss[q.subject]&&ss[q.subject].correct/ss[q.subject].attempts<.65)mix.weak++}$('#smartDescription').textContent=smart.length?`${smart.length} questions prioritized from what is due, weak, previously wrong and still unseen.`:'No adaptive items available yet. Start with unseen questions.';$('#smartMix').innerHTML=Object.entries(mix).filter(([,v])=>v).map(([k,v])=>`<span>${v} ${k}</span>`).join('')||'<span>fresh start</span>';
 const weak=Object.entries(ss).filter(([,v])=>v.attempts>=2).map(([k,v])=>[k,v.correct/v.attempts,v.attempts]).sort((a,b)=>a[1]-b[1]).slice(0,6);$('#weakSubjects').innerHTML=weak.length?weak.map(([k,r,n])=>`<div class="bar-row"><span>${escapeHtml(k)}</span><div class="bar-track"><div class="bar-fill ${r<.6?'bad':''}" style="width:${Math.round(r*100)}%"></div></div><strong>${Math.round(r*100)}%</strong></div>`).join(''):'<div class="empty">Solve a few questions to reveal weak subjects.</div>';
 const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const key=dayKey(d),count=app.attempts.filter(a=>dayKey(a.ts)===key).length;days.push({label:d.toLocaleDateString(undefined,{weekday:'short'}),count})}const max=Math.max(1,...days.map(d=>d.count));$('#activityChart').innerHTML=days.map(d=>`<div class="activity-col"><div class="activity-bar" style="height:${Math.max(3,d.count/max*78)}px" title="${d.count}"></div><small>${d.label}</small></div>`).join('');$('#activityCaption').textContent=`${days.reduce((s,d)=>s+d.count,0)} attempts in the last 7 days.`;
 const incorrect=incorrectQuestions().length,unseen=unseenQuestions().length;const priorities=[['Due reviews',due,'review'],['Incorrect to recover',incorrect,'review'],['Unseen high-yield',unseen,'practice'],['Bookmarks',bms,'review']].filter(x=>x[1]);$('#todayPlan').innerHTML=priorities.length?priorities.map(([name,n,v])=>`<div class="list-item"><span class="status-dot ${name.startsWith('Due')?'warn':''}"></span><div class="grow"><strong>${n} ${name}</strong><p>${v==='practice'?'Build retrieval volume':'Close the loop before adding more'}</p></div><button class="btn small" data-view-jump="${v}">Open</button></div>`).join(''):'<div class="empty">No backlog. Start a smart session.</div>';
 const recent=[...app.attempts].sort((a,b)=>b.ts-a.ts).slice(0,5);$('#recentActivity').innerHTML=recent.length?recent.map(a=>{const q=app.qMap.get(a.qid);return `<div class="list-item"><span class="status-dot ${a.correct?'good':'bad'}"></span><div class="grow"><strong>${a.correct?'Correct':'Incorrect'} · ${escapeHtml(q?.subject||'Question')}</strong><p>${escapeHtml(q?.stem||a.qid)}</p></div><span class="tiny muted">${new Date(a.ts).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></div>`}).join(''):'<div class="empty">Your attempts will appear here.</div>';
 bindViewJump()}
function bindViewJump(){$$('[data-view-jump]').forEach(b=>b.onclick=()=>navigate(b.dataset.viewJump))}
function activateReviewTab(tab='quick'){$$('[data-review-tab]').forEach(b=>{const active=b.dataset.reviewTab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false')});$$('[data-review-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.reviewPanel!==tab))}
document.addEventListener('click',e=>{const tab=e.target.closest?.('[data-review-tab]');if(tab)activateReviewTab(tab.dataset.reviewTab)});

function sessionSnapshot(){const s=app.session;if(!s||s.ended)return null;return {_neetSectionIndex:s._neetSectionIndex,_neetSectionStartedAt:s._neetSectionStartedAt,sessionId:s.id,qids:s.questions.map(q=>q.external_id),pos:s.pos,cfg:s.cfg,answers:s.answers,startedAt:s.startedAt,currentStart:s.currentStart,selected:s.selected,confidence:s.confidence,eliminateMode:s.eliminateMode,rated:s.rated,lastAttempt:s.lastAttempt,renderedOptions:s.renderedOptions,eliminated:$$('#qOptions .eliminated').map(b=>b.dataset.label),draftNote:$('#questionNote')?.value||'',draftAttemptNote:$('#attemptNote')?.value||'',savedAt:now()}}
function saveActiveSession(){if(!app.db||!app.session||app.session.ended)return;const payload=sessionSnapshot();app.savedSession=payload;return dbPut('runtime',{id:'active',payload}).catch(()=>toast('Session could not be saved. Keep this tab open.'))}
function restoreQuestionUi(){const s=app.session,q=currentQ();$$('#qOptions .option').forEach(b=>{b.classList.toggle('selected',b.dataset.label===s.selected);b.classList.toggle('eliminated',(s.eliminated||[]).includes(b.dataset.label));if(s.lastAttempt){b.classList.toggle('correct',q.options.some(o=>o.is_correct&&o.label===b.dataset.label));b.classList.toggle('wrong',b.dataset.label===s.selected&&!s.lastAttempt.correct)}});$$('.confidence button').forEach(b=>b.classList.toggle('active',Number(b.dataset.confidence)===s.confidence));$('#qEliminate').classList.toggle('soft',!!s.eliminateMode);$('#qEliminate').textContent=s.eliminateMode?'Eliminate: ON':'Eliminate mode';$('#questionNote').value=s.draftNote??stateFor(q.external_id).note??'';$('#attemptNote').value=s.draftAttemptNote||s.lastAttempt?.note||'';if(s.lastAttempt){$('#qSubmit').disabled=true;$('#feedbackTag').textContent=s.lastAttempt.correct?'Correct':'Incorrect';$('#feedbackTag').className='tag '+(s.lastAttempt.correct?'good':'bad');$('#feedbackTitle').textContent=s.lastAttempt.correct?'Nice retrieval':'Correct answer: '+q.options.find(o=>o.is_correct)?.label;$('#feedbackExplanation').textContent=q.answer_explanation||'No explanation provided.';$('#feedbackReference').textContent=q.reference_text||'';$('#mistakeCategory').value=s.lastAttempt.mistake||'';$('#qFeedback').classList.remove('hidden')}}
function restoreSessionPayload(p=app.savedSession){if(!p?.qids?.length)return false;const qs=p.qids.map(id=>app.qMap.get(id));if(qs.some(q=>!q)){toast('Download missing question bundles before resuming.');return false}if(app.session)clearInterval(app.session.timerId);app.session={...p,id:p.sessionId,questions:qs,pos:clamp(Number(p.pos)||0,0,qs.length-1),cfg:{...builtInPreset('rapid'),...p.cfg},answers:p.answers||[],timerId:null,ended:false};$('#practiceSetup').classList.add('hidden');$('#sessionSummary').classList.add('hidden');$('#practiceShell').classList.remove('hidden');if(app.session.lastAttempt){const old=app.session.lastAttempt;app.session.lastAttempt=app.attempts.find(a=>a.qid===old.qid&&a.ts===old.ts&&a.sessionId===old.sessionId)||old}navigate('practice');renderQuestion(true);startTimer();return true}
function buildSession(queue,cfg){if(app.session)clearInterval(app.session.timerId);if(!queue.length){toast('No questions match those filters');return}const count=Math.min(cfg.count||queue.length,queue.length);let qs=queue.slice(0,count);if(cfg.order==='random')qs=shuffle(qs);app.session={id:`s-${Date.now()}`,questions:qs,pos:0,cfg,answers:[],startedAt:now(),currentStart:now(),selected:null,confidence:null,eliminateMode:false,rated:false,lastAttempt:null,timerId:null,ended:false};$('#practiceSetup').classList.add('hidden');$('#sessionSummary').classList.add('hidden');$('#practiceShell').classList.remove('hidden');navigate('practice');startTimer();renderQuestion()}
function startSessionFromConfig(cfg){let qs=getFilteredQuestions(cfg);if(cfg.mode==='smart'&&!qs.length)qs=getFilteredQuestions({mode:'unseen',order:'random'});buildSession(qs,cfg)}
function currentQ(){return app.session?.questions[app.session.pos]}
function displayedOptions(q){let opts=q.options.map(o=>({...o}));if(app.session.cfg.shuffle)opts=shuffle(opts);return opts}
function renderQuestion(preserve=false){const s=app.session;if(!s||s.ended)return;const q=currentQ(),st=stateFor(q.external_id);if(!preserve){s.selected=null;s.confidence=null;s.eliminateMode=false;s.rated=false;s.lastAttempt=null;s.currentStart=now();s.renderedOptions=displayedOptions(q)}else if(!s.renderedOptions)s.renderedOptions=displayedOptions(q);$('#qProgress').textContent=`${s.pos+1} / ${s.questions.length}`;$('#qProgressFill').style.width=`${(s.pos+1)/s.questions.length*100}%`;$('#qSubject').textContent=q.subject;$('#qSubject').classList.toggle('hidden',!app.prefs.labels);$('#qTopic').textContent=q.topic;$('#qTopic').classList.toggle('hidden',!app.prefs.labels);$('#qDifficulty').textContent=difficultyName(q.difficulty);$('#qStem').textContent=q.stem;$('#qOptions').innerHTML=s.renderedOptions.map(o=>`<button class="option" data-label="${escapeHtml(o.label)}"><span class="letter">${escapeHtml(o.label)}</span><span>${escapeHtml(o.text)}</span></button>`).join('');$$('#qOptions .option').forEach(b=>b.onclick=()=>selectOption(b));$('#qBookmark').textContent=`${st.bookmarked?'★':'☆'} Bookmark`;$('#qFlag').textContent=`${st.flagged?'⚑':'⚐'} Flag`;$('#qEliminate').classList.remove('soft');$('#qEliminate').textContent='Eliminate mode';$('#qFeedback').classList.add('hidden');$('#qSubmit').disabled=false;$('#mistakeCategory').value='';$('#attemptNote').value='';$('#questionNote').value=st.note||'';$$('.confidence button').forEach(b=>b.classList.remove('active'));updateTimerLabel();if(preserve)restoreQuestionUi();saveActiveSession()}
function selectOption(btn){const s=app.session;if(!s||$('#qSubmit').disabled)return;if(s.eliminateMode){btn.classList.toggle('eliminated');return}$$('#qOptions .option').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');s.selected=btn.dataset.label;saveActiveSession()}
function elapsedCurrent(){return Math.max(0,Math.round((now()-app.session.currentStart)/1000))}
async function submitAnswer(auto=false){const s=app.session;if(!s||s.ended||$('#qSubmit').disabled)return;if(!s.selected&&!auto){toast('Choose an answer first');return}const q=currentQ();$('#qSubmit').disabled=true;let rec;try{rec=await recordAttempt(q,s.selected,{confidence:s.confidence,elapsed:elapsedCurrent(),sessionId:s.id})}catch(e){$('#qSubmit').disabled=false;toast('Answer was not saved. Please retry.');return}s.lastAttempt=rec;s.answers.push({qid:q.external_id,correct:rec.correct,selected:s.selected,confidence:s.confidence,attemptId:rec.id});if(s.cfg.feedback==='exam'){await nextQuestion(true);return}const correct=q.options.find(o=>o.is_correct);$$('#qOptions .option').forEach(b=>{if(b.dataset.label===correct?.label)b.classList.add('correct');else if(b.dataset.label===s.selected&&!rec.correct)b.classList.add('wrong')});$('#feedbackTag').textContent=rec.correct?'Correct':'Incorrect';$('#feedbackTag').className=`tag ${rec.correct?'good':'bad'}`;$('#feedbackTitle').textContent=rec.correct?'Nice retrieval':`Correct answer: ${correct?.label||'—'}`;$('#feedbackExplanation').textContent=q.answer_explanation||'No explanation provided.';$('#feedbackReference').textContent=q.reference_text||'';$('#qFeedback').classList.remove('hidden');if(!app.prefs.autoExplain)$('#feedbackExplanation').classList.add('hidden');else $('#feedbackExplanation').classList.remove('hidden');saveActiveSession();renderAll()}
async function skipQuestion(){const s=app.session;if(!s||s.lastAttempt||$('#qSubmit').disabled)return;$('#qSubmit').disabled=true;const q=currentQ();let rec;try{rec=await recordAttempt(q,null,{confidence:s.confidence,elapsed:elapsedCurrent(),sessionId:s.id,mistake:'Skipped'})}catch(e){$('#qSubmit').disabled=false;toast('Skip was not saved. Please retry.');return}s.lastAttempt=rec;s.answers.push({qid:q.external_id,correct:false,selected:null,confidence:s.confidence,attemptId:rec.id});if(s.cfg.feedback==='instant'){await applySrs(q.external_id,'again')}await nextQuestion(true)}
async function nextQuestion(fromExam=false){const s=app.session;if(!s)return;if(!fromExam&&s.cfg.feedback==='instant'&&s.lastAttempt&&!s.rated){await applySrs(currentQ().external_id,s.lastAttempt.correct?'good':'again')}if(s.pos+1>=s.questions.length){await finishSession();return}s.pos++;renderQuestion()}
async function finishSession(){const s=app.session;if(!s)return;s.ended=true;clearInterval(s.timerId);const correct=s.answers.filter(a=>a.correct).length,total=s.questions.length,pct=total?Math.round(correct/total*100):0;const rec={id:s.id,startedAt:s.startedAt,endedAt:now(),count:total,correct,accuracy:pct,mode:s.cfg.mode,feedback:s.cfg.feedback,subjects:[...new Set(s.questions.map(q=>q.subject))]};await dbPut('sessions',rec);app.sessions.unshift(rec);app.lastSession={...s,summary:rec};$('#practiceShell').classList.add('hidden');$('#practiceSetup').classList.add('hidden');$('#sessionSummary').classList.remove('hidden');$('#summaryScore').textContent=`${pct}%`;$('#scoreRing').style.setProperty('--score',`${pct*3.6}deg`);$('#summaryText').textContent=`${correct} correct out of ${total}. ${total-correct} need another retrieval pass.`;$('#summaryChips').innerHTML=`<span class="chip">${total} questions</span><span class="chip">${Math.round((rec.endedAt-rec.startedAt)/60000)} min</span><span class="chip">${s.cfg.feedback==='exam'?'Exam mode':'Instant feedback'}</span>`;app.session=null;app.savedSession=null;await dbPut("runtime",{id:"active",payload:null});renderAll()}
function startTimer(){const s=app.session;if(!s)return;clearInterval(s.timerId);s.timerId=setInterval(()=>{updateTimerLabel();if(s.cfg.timer==='question'){const left=s.cfg.seconds-elapsedCurrent();if(left<=0&&!$('#qSubmit').disabled)submitAnswer(true)}else if(s.cfg.timer==='session'){const total=s.cfg.seconds*s.questions.length,elapsed=Math.floor((now()-s.startedAt)/1000);if(total-elapsed<=0)finishSession()}},500)}
function updateTimerLabel(){const s=app.session;if(!s)return;if(s.cfg.timer==='off'){$('#qTimer').textContent='No timer';return}let sec;if(s.cfg.timer==='question')sec=Math.max(0,s.cfg.seconds-elapsedCurrent());else sec=Math.max(0,s.cfg.seconds*s.questions.length-Math.floor((now()-s.startedAt)/1000));$('#qTimer').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}

function reviewCollection(kind){return kind==='due'?dueQuestions():kind==='incorrect'?incorrectQuestions():kind==='bookmarked'?bookmarkedQuestions():app.questions.filter(q=>stateFor(q.external_id).note)}
function renderReview(){
 const kinds=[['due','dueList','reviewDue'],['incorrect','wrongList','reviewIncorrect'],['bookmarked','bookmarkList','reviewBookmarks'],['notes','notesList','reviewNotes']];
 kinds.forEach(([kind,id,countId])=>{const all=reviewCollection(kind);$('#'+countId).textContent=all.length;let controls=$('#'+id+'Controls');if(!controls){controls=document.createElement('div');controls.id=id+'Controls';controls.className='collection-tools';controls.innerHTML=`<input aria-label="Search ${kind}" placeholder="Search this collection"><div class="collection-pager"></div>`;$('#'+id).before(controls);controls.querySelector('input').oninput=()=>{controls.dataset.page='0';renderReview()}}
 const term=controls.querySelector('input').value.toLowerCase(),rows=all.filter(q=>`${q.subject} ${q.topic} ${q.stem} ${stateFor(q.external_id).note||''}`.toLowerCase().includes(term)),pages=Math.max(1,Math.ceil(rows.length/20)),page=Math.min(Number(controls.dataset.page)||0,pages-1);controls.dataset.page=page;
 $('#'+id).innerHTML=kind==='notes'?rows.slice(page*20,(page+1)*20).map(q=>`<div class="list-item"><div class="grow"><strong>${escapeHtml(q.subject)} · ${escapeHtml(q.topic)}</strong><p style="white-space:pre-wrap">${escapeHtml(stateFor(q.external_id).note)}</p></div><button class="btn small" data-practice-q="${escapeHtml(q.external_id)}">Open</button></div>`).join('')||'<div class="empty">No matching notes.</div>':listQuestions(rows.slice(page*20,(page+1)*20),'No matching items.');const pager=controls.querySelector('.collection-pager');pager.innerHTML=`<button class="btn small" data-page="-1" ${!page?'disabled':''}>Previous</button><span>${rows.length} items · ${page+1}/${pages}</span><button class="btn small" data-page="1" ${page===pages-1?'disabled':''}>Next</button>`;pager.querySelectorAll('button').forEach(b=>b.onclick=()=>{controls.dataset.page=page+Number(b.dataset.page);renderReview()})});bindPracticeButtons();
}
function listQuestions(qs,empty){return qs.length?qs.map(q=>{const st=stateFor(q.external_id);return `<div class="list-item"><span class="status-dot ${st.lastCorrect===true?'good':st.lastCorrect===false?'bad':'warn'}"></span><div class="grow"><strong>${escapeHtml(q.subject)} · ${escapeHtml(q.topic)}</strong><p>${escapeHtml(q.stem)}</p></div><button class="btn small" data-practice-q="${q.external_id}">Practice</button></div>`}).join(''):`<div class="empty">${escapeHtml(empty)}</div>`}
function bindPracticeButtons(){$$('[data-practice-q]').forEach(b=>b.onclick=()=>{const q=app.qMap.get(b.dataset.practiceQ);if(q)buildSession([q],{mode:'single',count:1,feedback:'instant',timer:'off',seconds:60,order:'adaptive',shuffle:app.prefs.shuffle})})}

function bankFilter(reset=true){
 let qs=window.NEETPG_PYQ?.filteredBankFromUi?.()||window.NEETPG_PHASE10?.filteredBankFromUi?.();
 if(!qs){const term=$('#bankSearch').value.trim().toLowerCase();qs=app.questions.filter(q=>{const st=stateFor(q.external_id),sub=$('#bankSubject').value,diff=$('#bankDifficulty').value,status=$('#bankStatus').value;return (!term||`${q.stem} ${q.subject} ${q.topic}`.toLowerCase().includes(term))&&(sub==='all'||q.subject===sub)&&(diff==='all'||q.difficulty===Number(diff))&&(status==='all'||status==='unseen'&&!st.attempts||status==='correct'&&st.lastCorrect===true||status==='incorrect'&&st.lastCorrect===false||status==='bookmarked'&&st.bookmarked||status==='due'&&st.dueAt&&st.dueAt<=now())})}
 app.filteredBank=qs;app.bankPage=reset===false?(app.bankPage||0):0;const pages=Math.max(1,Math.ceil(qs.length/50));app.bankPage=Math.min(app.bankPage,pages-1);
 $('#bankCount').textContent=`${qs.length} of ${app.questions.length} questions`;
 $('#bankBody').innerHTML=qs.slice(app.bankPage*50,(app.bankPage+1)*50).map(q=>{const st=stateFor(q.external_id);return `<tr><td class="stem-cell"><div title="${escapeHtml(q.stem)}">${escapeHtml(q.stem)}</div></td><td>${escapeHtml(q.subject)}</td><td>${escapeHtml(q.topic)}</td><td><span class="tag">${!st.attempts?'Unseen':st.lastCorrect?'Correct':'Incorrect'}</span></td><td><button class="btn small" data-practice-q="${escapeHtml(q.external_id)}">Solve</button></td></tr>`}).join('');
 let pager=$('#bankPager');if(!pager){pager=document.createElement('div');pager.id='bankPager';pager.className='collection-pager';$('#bankBody').closest('table').parentElement.after(pager)}pager.innerHTML=`<button class="btn small" data-page="-1" ${app.bankPage===0?'disabled':''}>Previous</button><span>Page ${app.bankPage+1} of ${pages}</span><button class="btn small" data-page="1" ${app.bankPage>=pages-1?'disabled':''}>Next</button>`;pager.querySelectorAll('button').forEach(b=>b.onclick=()=>{app.bankPage+=Number(b.dataset.page);bankFilter(false)});bindPracticeButtons();
}
function renderBank(){bankFilter()}

function renderBars(el,items,empty='No data yet.'){el.innerHTML=items.length?items.map(([label,val,count,cls=''])=>`<div class="bar-row"><span title="${escapeHtml(label)}">${escapeHtml(label)}</span><div class="bar-track"><div class="bar-fill ${cls}" style="width:${clamp(Math.round(val),0,100)}%"></div></div><strong>${Math.round(val)}%</strong></div>`).join(''):`<div class="empty">${empty}</div>`}
function renderAnalytics(){const ss=subjectStats();const subjectItems=Object.entries(ss).filter(([,v])=>v.attempts).map(([k,v])=>[k,v.correct/v.attempts*100,v.attempts,v.correct/v.attempts<.6?'bad':'']).sort((a,b)=>a[1]-b[1]);renderBars($('#subjectBars'),subjectItems,'Solve questions to generate subject analytics.');
 const mistakes={};for(const a of app.attempts.filter(a=>!a.correct&&a.mistake))mistakes[a.mistake]=(mistakes[a.mistake]||0)+1;const mt=Object.values(mistakes).reduce((s,n)=>s+n,0);renderBars($('#mistakeBars'),Object.entries(mistakes).map(([k,n])=>[k,mt?n/mt*100:0,n,'bad']).sort((a,b)=>b[1]-a[1]),'Classify mistakes after wrong answers to see the pattern.');
 const diffs=[1,2,3].map(d=>{const xs=app.attempts.filter(a=>(app.qMap.get(a.qid)?.difficulty||2)===d);return[difficultyName(d),xs.length?xs.filter(a=>a.correct).length/xs.length*100:0,xs.length,xs.length&&xs.filter(a=>a.correct).length/xs.length<.6?'bad':'']}).filter(x=>x[2]);renderBars($('#difficultyBars'),diffs,'No difficulty data yet.');
 const conf=[1,2,3,4,5].map(c=>{const xs=app.attempts.filter(a=>Number(a.confidence)===c);return[`Confidence ${c}`,xs.length?xs.filter(a=>a.correct).length/xs.length*100:0,xs.length,'']}).filter(x=>x[2]);renderBars($('#confidenceBars'),conf,'Use confidence ratings during practice to calibrate certainty.');
 const ts=Object.entries(topicStats()).filter(([,v])=>v.attempts>=2).map(([k,v])=>[k,v.correct/v.attempts,v.attempts]).sort((a,b)=>a[1]-b[1]).slice(0,8);$('#nextTopics').innerHTML=ts.length?ts.map(([k,r,n],i)=>`<div class="list-item"><span class="tag">${i+1}</span><div class="grow"><strong>${escapeHtml(k)}</strong><p>${Math.round(r*100)}% across ${n} attempts</p></div></div>`).join(''):'<div class="empty">More attempts are needed before topic recommendations become useful.</div>';
 $('#sessionHistory').innerHTML=app.sessions.length?app.sessions.slice(0,8).map(s=>`<div class="list-item"><span class="status-dot ${s.accuracy>=70?'good':s.accuracy<50?'bad':'warn'}"></span><div class="grow"><strong>${s.accuracy}% · ${s.correct}/${s.count}</strong><p>${escapeHtml(s.mode)} · ${new Date(s.startedAt).toLocaleString()}</p></div></div>`).join(''):'<div class="empty">Completed sessions will appear here.</div>'}

function renderSettings(){const p=app.prefs;$('#sTheme').value=p.theme;$('#sAccent').value=p.accent;$('#sDensity').value=p.density;$('#sFont').value=p.font;$('#sDefaultMode').value=p.defaultMode;$('#sDefaultCount').value=p.defaultCount;setSwitch($('#sShuffle'),p.shuffle);setSwitch($('#sLabels'),p.labels);setSwitch($('#sAutoExplain'),p.autoExplain);renderSavedPresets()}
function setSwitch(el,on){el.classList.toggle('on',!!on);el.dataset.on=on?'1':'0'}
function readSwitch(el){return el.dataset.on==='1'}
function renderSavedPresets(){const el=$('#savedPresets');el.innerHTML='<option value="">Saved presets…</option>'+app.prefs.presets.map((p,i)=>`<option value="${i}">${escapeHtml(p.name)}</option>`).join('')}
async function exportBackup(){const data={version:3,runtime:app.savedSession,extras:Object.fromEntries(['neetpg2027-phase12-planner','neetpg2027-exam-v9-history','neetpg2027-exam-target'].map(k=>[k,localStorage.getItem(k)])),vault:await window.NeuralVaultDB?.loadState(),vaultRevisions:await window.NeuralVaultDB?.exportRevisions(),exportedAt:iso(now()),prefs:app.prefs,qstate:[...app.states.values()],attempts:app.attempts,sessions:app.sessions,custom:app.custom};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`NEETPG2027-backup-${dayKey(now())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exported')}
async function importBackupFile(file){const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.qstate)||!Array.isArray(data.attempts)||data.qstate.some(x=>!x||typeof x.qid!=='string')||data.attempts.some(x=>!x||typeof x.qid!=='string'||!Number.isFinite(x.ts))||['sessions','custom'].some(k=>data[k]&&!Array.isArray(data[k])))throw new Error('Not a NEETPG2027 backup');for(const x of data.qstate){if(typeof x.qid!=='string')throw new Error('Invalid question state');if(new Date(x.updatedAt||0)>=new Date(stateFor(x.qid).updatedAt||0))await dbPut('qstate',x)}const key=a=>[a.sessionId,a.qid,a.ts,a.selected].join('|'),known=new Set(app.attempts.map(key));for(const x of data.attempts){if(typeof x.qid!=='string'||!Number.isFinite(x.ts))throw new Error('Invalid attempt');if(known.has(key(x)))continue;const y={...x};delete y.id;await dbAdd('attempts',y);known.add(key(x))}for(const x of data.sessions||[])await dbPut('sessions',x);for(const x of data.custom||[])await dbPut('custom',x);if(data.runtime?.qids?.length&&!app.session){app.savedSession=data.runtime;await dbPut('runtime',{id:'active',payload:data.runtime})}for(const k of ['neetpg2027-phase12-planner','neetpg2027-exam-v9-history','neetpg2027-exam-target'])if(typeof data.extras?.[k]==='string')localStorage.setItem(k,data.extras[k]);if(data.vault?.notes&&window.NeuralVaultDB){const old=await NeuralVaultDB.loadState()||{notes:[]},notes=new Map(old.notes.map(n=>[n.id,n]));for(const n of data.vault.notes)if(n.id&&(!notes.has(n.id)||new Date(n.updatedAt)>new Date(notes.get(n.id).updatedAt)))notes.set(n.id,n);await NeuralVaultDB.saveState({...old,notes:[...notes.values()]});await NeuralVaultDB.importRevisions(data.vaultRevisions||[])}if(data.prefs){app.prefs={...DEFAULTS,...data.prefs};savePrefs()}await loadState();await loadQuestions();populateFilters();renderAll();toast('Backup imported')}
async function importCustomQuestions(file){const raw=JSON.parse(await file.text()),arr=Array.isArray(raw)?raw:(raw.questions||[]);let n=0;for(const item of arr){if(!item?.stem||!Array.isArray(item.options)||item.options.length<2)continue;const correct=item.options.filter(o=>o.is_correct);if(correct.length!==1)continue;const q={...item,external_id:item.external_id||`custom-${Date.now()}-${n}`,reference_text:item.reference_text||`Custom import; Subject: ${item.subject||'Custom'}; Topic: ${item.topic||'Imported'}.`,difficulty:Number(item.difficulty||2),is_clinical:!!item.is_clinical,is_integrated:!!item.is_integrated};await dbPut('custom',q);n++}await loadState();await loadQuestions();populateFilters();renderAll();toast(`${n} custom questions imported`)}
async function resetAll(){if(!confirm('Delete all local NEETPG2027 progress, notes, custom questions and settings on this device?'))return;if(app.session)clearInterval(app.session.timerId);app.session=null;app.savedSession=null;for(const s of ['qstate','attempts','sessions','custom','runtime'])await dbClear(s);localStorage.removeItem(SETTINGS_KEY);localStorage.removeItem('neetpg2027-v2-migrated');localStorage.removeItem(QSTATE_MIRROR);app.prefs={...DEFAULTS};savePrefs();await loadState();await loadQuestions();populateFilters();renderAll();toast('Local data reset')}

function renderAll(){const view=$('.view.active')?.id.replace('view-','');if(view==='dashboard')renderDashboard();if(view==='review')renderReview();if(view==='bank')renderBank();if(view==='analytics')renderAnalytics();const due=$('#navDue');if(due)due.textContent=dueQuestions().length;emitUi('data-change',{source:'renderAll'})}
function applyDefaultsToPractice(){const p=app.prefs;$('#pMode').value=p.defaultMode;$('#pCount').value=p.defaultCount}
function builtInPreset(name){const base={mode:'smart',subject:'all',topic:'all',difficulty:'all',clinical:'all',integrated:'all',count:15,feedback:'instant',timer:'off',seconds:60,order:'adaptive',shuffle:app.prefs.shuffle};if(name==='rapid')return{...base,count:15};if(name==='inicet')return{...base,count:25,difficulty:'2',integrated:'all',timer:'question',seconds:60,order:'weakest'};if(name==='errors')return{...base,mode:'incorrect',count:25,order:'adaptive'};if(name==='grand')return{...base,mode:'all',count:100,feedback:'exam',timer:'question',seconds:60,order:'random'};return base}
function setPracticeForm(c){$('#pMode').value=c.mode||'smart';$('#pSubject').value=c.subject||'all';updateTopics();$('#pTopic').value=c.topic||'all';$('#pDifficulty').value=c.difficulty||'all';$('#pClinical').value=c.clinical||'all';$('#pIntegrated').value=c.integrated||'all';$('#pCount').value=String(c.count||15);$('#pFeedback').value=c.feedback||'instant';$('#pTimer').value=c.timer||'off';$('#pSeconds').value=c.seconds||60;$('#pOrder').value=c.order||'adaptive';$('#pShuffle').value='default'}
async function saveCurrentPreset(){const name=prompt('Preset name');if(!name)return;app.prefs.presets.push({name,cfg:sessionConfigFromForm()});savePrefs();renderSavedPresets();toast('Preset saved')}

function bindEvents(){document.addEventListener('click',e=>{if(e.target.closest('#practiceShell'))setTimeout(saveActiveSession,0)});document.addEventListener('input',e=>{if(e.target.closest('#practiceShell'))saveActiveSession()});window.addEventListener('pagehide',saveActiveSession);$('#themeToggle')?.addEventListener('click',()=>{app.prefs.theme=document.body.dataset.theme==='dark'?'light':'dark';savePrefs();$('#sTheme').value=app.prefs.theme});$$('.nav button[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#menuBtn').onclick=()=>{$('#sidebar').classList.add('open');$('#mobileOverlay').classList.add('show')};$('#mobileOverlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobileOverlay').classList.remove('show')};$('#shortcutsBtn').onclick=()=>$('#shortcutsModal').classList.add('show');$('#closeShortcuts').onclick=()=>$('#shortcutsModal').classList.remove('show');$('#shortcutsModal').onclick=e=>{if(e.target===$('#shortcutsModal'))$('#shortcutsModal').classList.remove('show')};const refresh=$('#refreshDashboard');if(refresh)refresh.onclick=renderDashboard;const smart=$('#startSmart');if(smart)smart.onclick=()=>startSessionFromConfig({...builtInPreset('rapid'),mode:'smart',count:Number(app.prefs.defaultCount)||15});$('#pSubject').onchange=updateTopics;$('#startCustom').onclick=()=>startSessionFromConfig(sessionConfigFromForm());$$('#presetChips [data-preset]').forEach(b=>b.onclick=()=>{setPracticeForm(builtInPreset(b.dataset.preset));toast(`${b.textContent.trim()} loaded`)});$('#savePreset').onclick=saveCurrentPreset;$('#savedPresets').onchange=e=>{const p=app.prefs.presets[Number(e.target.value)];if(p)setPracticeForm(p.cfg)};
 $('#qSubmit').onclick=()=>submitAnswer(false);$('#qNext').onclick=()=>nextQuestion(false);$('#qSkip').onclick=skipQuestion;$('#qBookmark').onclick=()=>currentQ()&&toggleBookmark(currentQ().external_id);$('#qFlag').onclick=()=>currentQ()&&toggleFlag(currentQ().external_id);$('#qEliminate').onclick=()=>{if(!app.session)return;app.session.eliminateMode=!app.session.eliminateMode;$('#qEliminate').classList.toggle('soft',app.session.eliminateMode);$('#qEliminate').textContent=app.session.eliminateMode?'Eliminate: ON':'Eliminate mode'};$$('.confidence button').forEach(b=>b.onclick=()=>{if(!app.session)return;app.session.confidence=Number(b.dataset.confidence);$$('.confidence button').forEach(x=>x.classList.toggle('active',x===b))});$$('[data-rating]').forEach(b=>b.onclick=async()=>{if(!app.session)return;await applySrs(currentQ().external_id,b.dataset.rating);app.session.rated=true;$$('[data-rating]').forEach(x=>x.classList.toggle('primary',x===b))});$('#mistakeCategory').onchange=async e=>{if(!app.session?.lastAttempt)return;app.session.lastAttempt.mistake=e.target.value;await updateAttempt(app.session.lastAttempt);renderAnalytics()};$('#attemptNote').onchange=async e=>{if(!app.session?.lastAttempt)return;app.session.lastAttempt.note=e.target.value.trim();await updateAttempt(app.session.lastAttempt)};$('#questionNote').onchange=e=>currentQ()&&saveQuestionNote(currentQ().external_id,e.target.value);$('#newSession').onclick=()=>{$('#sessionSummary').classList.add('hidden');$('#practiceSetup').classList.remove('hidden')};$('#reviewSession').onclick=()=>{if(!app.lastSession)return;buildSession(app.lastSession.questions,{...app.lastSession.cfg,feedback:'instant',timer:'off',count:app.lastSession.questions.length})};$('#startDue').onclick=()=>startSessionFromConfig({...builtInPreset('rapid'),mode:'due',count:25});
 for(const id of ['bankSearch','bankSubject','bankStatus','bankDifficulty'])$(`#${id}`).oninput=bankFilter;$('#practiceFiltered').onclick=()=>buildSession(app.filteredBank,{...builtInPreset('rapid'),mode:'filtered',count:Math.min(50,app.filteredBank.length),order:'adaptive'});$('#customImport').onchange=async e=>{if(e.target.files[0])try{await importCustomQuestions(e.target.files[0])}catch(err){toast(err.message)}e.target.value=''};
 for(const id of ['sShuffle','sLabels','sAutoExplain'])$(`#${id}`).onclick=e=>setSwitch(e.currentTarget,!readSwitch(e.currentTarget));$('#saveSettings').onclick=()=>{app.prefs={...app.prefs,theme:$('#sTheme').value,accent:$('#sAccent').value,density:$('#sDensity').value,font:$('#sFont').value,defaultMode:$('#sDefaultMode').value,defaultCount:$('#sDefaultCount').value,shuffle:readSwitch($('#sShuffle')),labels:readSwitch($('#sLabels')),autoExplain:readSwitch($('#sAutoExplain'))};savePrefs();applyDefaultsToPractice();toast('Settings saved')};$('#exportBackup').onclick=exportBackup;$('#importBackup').onchange=async e=>{if(e.target.files[0])try{await importBackupFile(e.target.files[0])}catch(err){toast(err.message)}e.target.value=''};$('#resetAll').onclick=resetAll;$('#installPwa').onclick=async()=>{if(app.installPrompt){app.installPrompt.prompt();await app.installPrompt.userChoice;app.installPrompt=null}else toast('Use Safari Share → Add to Home Screen')};$('#cacheRefresh').onclick=async()=>{if(navigator.serviceWorker?.controller){navigator.serviceWorker.controller.postMessage({type:'REFRESH_CACHE'});toast('Offline cache refresh requested')}else toast('Reload once to activate offline mode')};
 document.addEventListener('keydown',e=>{if(!app.session||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const q=currentQ();if(['1','2','3','4'].includes(e.key)){const i=Number(e.key)-1;const b=$$('#qOptions .option')[i];if(b)selectOption(b)}else if(e.key==='Enter'){e.preventDefault();if(!$('#qFeedback').classList.contains('hidden'))nextQuestion(false);else submitAnswer(false)}else if(e.key.toLowerCase()==='b')toggleBookmark(q.external_id);else if(e.key.toLowerCase()==='f')toggleFlag(q.external_id);else if(e.key.toLowerCase()==='e')$('#qEliminate').click()});
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();app.installPrompt=e});window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(app.prefs.theme==='system')applyPrefs()})}
function applyNeuralVaultDeepLink(){
  const params=new URLSearchParams(location.search);
  const qid=params.get('nvq'),qids=params.get('nvqs'),subject=params.get('nvsubject'),topic=params.get('nvtopic'),practice=params.get('nvpractice')==='1';
  if(!qid&&!qids&&!subject&&!topic)return false;
  const clear=()=>history.replaceState({},'',location.pathname+location.hash);
  if(qid){
    const q=app.qMap.get(qid);
    if(q){
      buildSession([q],{...builtInPreset('rapid'),mode:'single',count:1,feedback:'instant',timer:'off',order:'adaptive'});
      toast('Opened from NeuralVault');
      clear();
      return true;
    }
  }
  if(qids){
    const exact=qids.split(',').map(id=>app.qMap.get(id)).filter(Boolean);
    if(exact.length){
      buildSession(exact,{...builtInPreset('rapid'),mode:'neuralvault',count:exact.length,feedback:'instant',timer:'off',order:'adaptive'});
      toast('Started '+exact.length+' matched question'+(exact.length===1?'':'s')+' from NeuralVault');
      clear();
      return true;
    }
  }
  if(subject||topic){
    navigate('bank');
    if(subject&&[...$('#bankSubject').options].some(o=>o.value===subject))$('#bankSubject').value=subject;
    $('#bankSearch').value=topic||'';
    bankFilter();
    if(practice&&app.filteredBank.length){
      const count=Math.min(15,app.filteredBank.length);
      buildSession(app.filteredBank,{...builtInPreset('rapid'),mode:'neuralvault',count,order:'adaptive'});
      toast('Started '+count+' matched question'+(count===1?'':'s')+' from NeuralVault');
    }else{
      toast(app.filteredBank.length+' matching question'+(app.filteredBank.length===1?'':'s')+' from NeuralVault');
    }
    clear();
    return true;
  }
  return false;
}
function updateOnline(){$('#offlineBadge').textContent=navigator.onLine?'Online':'Offline';$('#offlineBadge').className=`tag ${navigator.onLine?'good':'warn'}`}

async function registerServiceWorker(){if('serviceWorker'in navigator)try{await navigator.serviceWorker.register('./sw.js')}catch(e){console.warn('SW registration failed',e)}}
async function init(){try{loadPrefs();app.db=await openDb();await loadState();await loadQuestions();app.savedSession=(await dbAll("runtime")).find(x=>x.id==="active")?.payload||null;await migrateV1();populateFilters();bindEvents();applyDefaultsToPractice();renderSettings();renderAll();updateOnline();registerServiceWorker();bindViewJump();applyNeuralVaultDeepLink();document.body.dataset.coreReady='1';emitUi('core-ready',{questions:app.questions.length})}catch(err){console.error(err);document.querySelector('.content').innerHTML=`<div class="card"><h2 class="danger-text">Study engine could not start</h2><p>${escapeHtml(err.message)}</p><p class="muted">Reload the page. If this persists, export any available browser data before clearing site storage.</p></div>`}}
init();
